 periodBounds(mode=this.reportPeriod){if(mode!=='rolling')return yearBounds();const end=state.today,back=new Date(end+'T12:00:00Z'),month=back.getUTCMonth();back.setUTCFullYear(back.getUTCFullYear()-1);if(back.getUTCMonth()!==month)back.setUTCDate(0);return [back.toISOString().slice(0,10),end];},
 chart(start,end){const events=state.completions.filter(e=>e.date>=start&&e.date<=end),first=new Date(start+'T12:00:00Z'),last=new Date(end+'T12:00:00Z'),months=[];let d=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),1,12));while(d<=last){const key=d.toISOString().slice(0,7);months.push({key,label:d.toLocaleDateString('da-DK',{month:'short',year:'2-digit',timeZone:'UTC'}),count:events.filter(e=>e.date.startsWith(key)).length});d.setUTCMonth(d.getUTCMonth()+1);}const max=Math.max(1,...months.map(m=>m.count)),step=660/Math.max(1,months.length),ktm=state.visits.filter(v=>v.date>=start&&v.date<=end).sort((a,b)=>cmp(a.date,b.date)),lastVisit=ktm[ktm.length-1];return `<div class="reportchart"><h3>Gennemgange pr. måned</h3><svg viewBox="0 0 760 270" role="img" aria-label="Gennemgange pr. måned; sidste KTM-besøg markeret med gul pil"><line x1="45" y1="210" x2="720" y2="210" stroke="#c9d7e1"/>${months.map((m,i)=>{const bar=Math.min(36,step*.6),x=55+i*step+(step-bar)/2,h=m.count/max*145;return `<rect x="${x}" y="${210-h}" width="${bar}" height="${Math.max(1,h)}" rx="5" fill="#628db3"/><text x="${x+bar/2}" y="${201-h}" text-anchor="middle" font-size="12" fill="#54718a">${m.count}</text><text x="${x+bar/2}" y="235" text-anchor="middle" font-size="10" fill="#71889a">${m.label}</text>`;}).join('')}${lastVisit?(()=>{const i=months.findIndex(m=>m.key===lastVisit.date.slice(0,7)),x=55+(i+.5)*step;return `<line x1="${x}" y1="32" x2="${x}" y2="212" stroke="#c69a25" stroke-width="2" stroke-dasharray="4 4"/><path d="M${x-5} 40L${x} 31L${x+5} 40" fill="none" stroke="#c69a25" stroke-width="2"/><text x="${Math.max(130,Math.min(630,x))}" y="22" text-anchor="middle" font-size="12" fill="#a17b1c">Sidste besøg · ${fmt(lastVisit.date)}</text>`;})():''}</svg></div>`;},
 reportSummary(mode,includeMap=true,localized=false){const t=key=>localized?ui(key):key,[a,b]=this.periodBounds(mode),s=this.stats(a,b),ids=new Set(state.cards.map(c=>c.id)),covered=[...s.done].filter(id=>ids.has(id)).length;return `<section class="report"><div class="eyebrow">${state.settings.congregation?esc(state.settings.congregation):t('DISTRIKT')}</div><h1>${mode==='rolling'?t('Seneste 12 måneder'):t('Tjenesteår')+' '+yearLabel(year)}</h1><small>${fmt(a)} – ${fmt(b)} · ${t('Rapport udarbejdet den')} ${fmt(state.today)}</small><div class="metrics"><div><small>${t('Gennemgange')}</small><strong>${s.events.length}</strong></div><div><small>${t('Anslåede besøg')}</small><strong>${s.visits}</strong></div><div><small>${t('Dækning af aktuelle kort')}</small><strong>${state.cards.length?Math.round(covered/state.cards.length*100):0}%</strong></div></div><p class="hint">${t('Gentagne gennemgange tæller med hver gang i gennemgange og anslåede besøg. Besøg er et skøn ud fra kortenes besøgstal, ikke registrerede faktiske husbesøg. Dækning tæller hvert aktuelt kort én gang.')}</p>${localized?this.reportChart(a,b):this.chart(a,b)}${includeMap?'<h3>'+t('Gennemgåede distrikter')+'</h3>'+ReportMap.html(localized):''}</section>`;},
