 recurrenceField(n){return `<label>${ui('Gentagelse')}</label><select name="repeat_weekday"><option value="" ${!n.recurrence?'selected':''} data-ui="Ingen gentagelse">${esc(I18n.text('Ingen gentagelse'))}</option>${this.weekdays.map((day,i)=>`<option value="${i}" ${n.recurrence?.weekday===i?'selected':''} data-ui="${day}">${esc(I18n.text(day))}</option>`).join('')}</select><p class="hint">${ui('Ugentligt på den valgte dag. Udført gemmer historikken og flytter næste gang til efter i dag. Missede uger opretter ikke kopier. Ingen kort flyttes automatisk.')}</p>${this.taskSchedule(n)}${n.task_history?.length?`<details><summary>${ui('Afslutningshistorik · {count}',{count:n.task_history.length})}</summary>${[...n.task_history].reverse().map(h=>`<p>${ui('Planlagt {due} · udført {date}',{due:fmt(h.due),date:fmt(h.date)})}</p>`).join('')}</details>`:''}`;},
